insert into private.exercise_answer_keys (question_id, case_sensitive, explanation_markdown) values
  ('72000000-0000-4000-c000-000000000001'::uuid, false, 'Phần thi IELTS Reading kéo dài chính xác 60 phút cho cả 3 bài đọc với 40 câu hỏi, không có thêm thời gian chuyển đáp án.'),
  ('72000000-0000-4000-c000-000000000002'::uuid, false, 'Trung bình cộng là (6.5 + 7.0 + 6.0 + 6.5) / 4 = 6.5. Điểm Overall chính thức là 6.5.'),
  ('72000000-0000-4000-c000-000000000003'::uuid, false, 'Ba phần thi Listening, Reading và Writing diễn ra liên tiếp trong 2 giờ 45 phút mà không có giải lao giữa giờ.'),
  ('72000000-0000-4000-c000-000000000004'::uuid, false, 'False. Viết thư là yêu cầu của IELTS General Training Task 1. Academic Task 1 yêu cầu mô tả và phân tích biểu đồ, bản đồ hoặc quy trình.'),
  ('72000000-0000-4000-c000-000000000005'::uuid, false, 'Theo quy chế chấm điểm IELTS, đuôi .25 làm tròn lên .5, và đuôi .75 làm tròn lên 1.0 (round up).'),
  ('72000000-0000-4000-c000-000000000006'::uuid, false, 'IELTS Listening có 4 phần (Parts) với tổng cộng đúng 40 câu hỏi.'),
  ('72000000-0000-4000-c000-000000000007'::uuid, false, 'Coherence & Cohesion (CC) đánh giá tính mạch lạc của bài viết và sự liên kết logic giữa các câu, các đoạn.'),
  ('72000000-0000-4000-c000-000000000008'::uuid, false, 'Band 7.0 GRA yêu cầu người viết thường xuyên tạo ra các câu không có lỗi ngữ pháp (''frequent error-free sentences'').'),
  ('72000000-0000-4000-c000-000000000009'::uuid, false, 'Lexical Resource 7.0 nhấn mạnh việc dùng từ vựng ít phổ biến và thể hiện nhận thức về collocations cũng như phong cách học thuật.'),
  ('72000000-0000-4000-c000-000000000010'::uuid, false, 'False. Để đạt Band 7.0+ Task Response, bài viết bắt buộc phải thể hiện lập trường rõ ràng xuyên suốt bài viết (''a clear position throughout'').'),
  ('72000000-0000-4000-c000-000000000011'::uuid, false, 'Coherence and Cohesion thường được viết tắt là CC.'),
  ('72000000-0000-4000-c000-000000000012'::uuid, false, 'Lexical Resource thường được viết tắt là LR.'),
  ('72000000-0000-4000-c000-000000000013'::uuid, false, 'Task 2 chiếm 2/3 tổng số điểm Writing, do đó phân bổ chuẩn là 20 phút cho Task 1 và 40 phút cho Task 2.'),
  ('72000000-0000-4000-c000-000000000014'::uuid, false, 'Khác với thi giấy có 10 phút chép đáp án, thi máy tính chỉ có 2 phút để xem lại toàn bộ câu trả lời trước khi hệ thống khóa bài.'),
  ('72000000-0000-4000-c000-000000000015'::uuid, false, 'Hệ thống thi máy cho phép thí sinh bôi đen văn bản (Highlight) và thêm ghi chú (Note) bằng cách nhấp chuột phải.'),
  ('72000000-0000-4000-c000-000000000016'::uuid, false, 'True. Đồng hồ trên phần mềm thi chính thức sẽ cảnh báo màu đỏ khi thời gian còn lại dưới 10 phút và 5 phút.'),
  ('72000000-0000-4000-c000-000000000017'::uuid, false, 'Phím Tab cho phép nhảy nhanh sang trường nhập liệu tiếp theo mà không cần dùng chuột.'),
  ('72000000-0000-4000-c000-000000000018'::uuid, false, 'Khuyến nghị không dành quá 17 phút cho Passage 1 để đảm bảo đủ thời gian cho Passage 3 phức tạp hơn.'),
  ('72000000-0000-4000-c000-000000000019'::uuid, false, 'Phân tích câu chứa bằng chứng và tìm ra lý do khiến mình mắc bẫy là cốt lõi để không lặp lại lỗi sai.'),
  ('72000000-0000-4000-c000-000000000020'::uuid, false, 'Đây là lỗi chính tả (Spelling Mistake) do thiếu chữ ''r'', khiến câu trả lời bị chấm 0 điểm dù đã nghe đúng.'),
  ('72000000-0000-4000-c000-000000000021'::uuid, false, 'Evidence trích dẫn và bài học rút ra phòng ngừa lỗi là 2 yếu tố trọng tâm của một cuốn error log chất lượng.'),
  ('72000000-0000-4000-c000-000000000022'::uuid, false, 'False. Luôn vận dụng ngữ cảnh (context clues) và không bao giờ bỏ trống bất kỳ câu trả lời nào trong kỳ thi IELTS vì không bị trừ điểm câu sai.'),
  ('72000000-0000-4000-c000-000000000023'::uuid, false, 'Distractor là từ/ý gây nhiễu, thường xuất hiện trước khi người nói sửa lại thông tin chính xác.'),
  ('72000000-0000-4000-c000-000000000024'::uuid, false, 'Thí sinh phải trả lời 100% các câu hỏi, kể cả phỏng đoán ở những câu không chắc chắn.'),
  ('72000000-0000-4000-c000-000000000025'::uuid, false, 'Matching Headings đòi hỏi hiểu ý chính và mục đích của toàn bộ đoạn văn, phù hợp với thao tác Skimming.'),
  ('72000000-0000-4000-c000-000000000026'::uuid, false, 'Scanning di chuyển mắt tìm nhanh các ký tự số (ví dụ: 1845, 1999) giúp định vị vị trí câu trả lời trong vài giây.'),
  ('72000000-0000-4000-c000-000000000027'::uuid, false, 'Tên riêng viết hoa và các con số/thống kê là những ''mỏ neo thị giác'' (visual anchors) nổi bật nhất trên trang văn bản.'),
  ('72000000-0000-4000-c000-000000000028'::uuid, false, 'False. Đây là bẫy phổ biến trong Cambridge. Người ra đề thường đặt từ khóa giống hệt trong câu nhiễu, còn thông tin đúng lại dùng paraphrase.'),
  ('72000000-0000-4000-c000-000000000029'::uuid, false, 'Skimming là kỹ thuật đọc lướt nắm ý chính.'),
  ('72000000-0000-4000-c000-000000000030'::uuid, false, 'Scanning là kỹ thuật đọc quét định vị chi tiết.'),
  ('72000000-0000-4000-c000-000000000031'::uuid, false, 'Head noun là ''The impact'' (danh từ số ít), do đó động từ to be phải chia số ít là ''is''.'),
  ('72000000-0000-4000-c000-000000000032'::uuid, false, 'Cấu trúc ''The number of'' đi với động từ số ít, kết hợp với ''over the last three years'' dùng hiện tại hoàn thành -> ''has risen''.'),
  ('72000000-0000-4000-c000-000000000033'::uuid, false, '''A number of'' + V số nhiều (have questioned) là đúng. ''Every + N số ít'' + V số ít (is required) là đúng. ''Each of'' và ''Neither of'' chuẩn học thuật phải đi với V số ít.'),
  ('72000000-0000-4000-c000-000000000034'::uuid, false, 'False. Economics (ngành kinh tế học), Physics, Mathematics là tên môn học, luôn là danh từ không đếm được và đi với động từ số ít.'),
  ('72000000-0000-4000-c000-000000000035'::uuid, false, 'Head noun là ''A wide range'' (danh từ số ít chỉ tập hợp), động từ chia ''provides''.'),
  ('72000000-0000-4000-c000-000000000036'::uuid, false, 'Quy tắc ''Neither... nor...'': Động từ hòa hợp với chủ ngữ gần nó nhất. ''the students'' là số nhiều, thì quá khứ chia ''were''.'),
  ('72000000-0000-4000-c000-000000000037'::uuid, false, 'Trong tiếng Anh, đã dùng ''Although'' ở mệnh đề phụ thì mệnh đề chính KHÔNG dùng ''but'' và phải có dấu phẩy ngăn cách 2 mệnh đề.'),
  ('72000000-0000-4000-c000-000000000038'::uuid, false, 'Mệnh đề quan hệ không xác định dùng ''which'' đứng sau dấu phẩy để bổ nghĩa cho toàn bộ ý của mệnh đề đứng trước.'),
  ('72000000-0000-4000-c000-000000000039'::uuid, false, '''Whereas'' và ''While'' là hai liên từ phụ thuộc đắt giá để chỉ sự đối lập trong câu phức. ''Furthermore'' và ''Consequently'' là trạng từ liên kết.'),
  ('72000000-0000-4000-c000-000000000040'::uuid, false, 'False. ''That'' tuyệt đối không bao giờ được sử dụng trong mệnh đề quan hệ có dấu phẩy (non-defining).'),
  ('72000000-0000-4000-c000-000000000041'::uuid, false, '''Although'' là liên từ nhượng bộ phổ biến và chuẩn mực nhất trong văn viết học thuật.'),
  ('72000000-0000-4000-c000-000000000042'::uuid, false, 'Mệnh đề quan hệ chủ động được rút gọn bằng cách chuyển động từ sang dạng V-ing (''consisting'').'),
  ('72000000-0000-4000-c000-000000000043'::uuid, false, 'Câu dùng ''Evidence suggests that... may impair'' thể hiện tính cẩn trọng khoa học, không phán xét phiến diện.'),
  ('72000000-0000-4000-c000-000000000044'::uuid, false, 'Cấu trúc chuẩn: ''It is believed that + S + V'' truyền tải thông tin khách quan một cách tự nhiên.'),
  ('72000000-0000-4000-c000-000000000045'::uuid, false, '''Tend to'' (có xu hướng) và ''Are likely to'' (có khả năng) làm giảm bớt tính khẳng định tuyệt đối, đúng chuẩn mực viết học thuật.'),
  ('72000000-0000-4000-c000-000000000046'::uuid, false, 'True. Dạng bài Process tập trung vào đối tượng được xử lý (ví dụ: ''The tea leaves are harvested, dried and packaged'') nên thể bị động là bắt buộc.'),
  ('72000000-0000-4000-c000-000000000047'::uuid, false, 'Cụm ''It is widely accepted that...'' mang nghĩa ''Người ta thừa nhận rộng rãi rằng...''.'),
  ('72000000-0000-4000-c000-000000000048'::uuid, false, 'Trạng từ của ''probable'' là ''probably''.'),
  ('72000000-0000-4000-c000-000000000049'::uuid, false, 'Công thức đảo ngữ với hiện tại đơn: ''Not only + does + S + V(nguyên mẫu)... but S also...''.'),
  ('72000000-0000-4000-c000-000000000050'::uuid, false, '''Under no circumstances'' (Trong bất kỳ trường hợp nào cũng không) bắt buộc đảo trợ động từ lên trước chủ ngữ: ''should companies disclose''.'),
  ('72000000-0000-4000-c000-000000000051'::uuid, false, '''Seldom'' và ''Rarely'' mang nghĩa hiếm khi, phủ định bán phần nên bắt buộc dùng đảo ngữ khi đứng đầu câu.'),
  ('72000000-0000-4000-c000-000000000052'::uuid, false, 'False. Cấu trúc câu chẻ cố định là ''It is/was + X + that/who...'', không dùng ''what''.'),
  ('72000000-0000-4000-c000-000000000053'::uuid, false, 'Cấu trúc: ''Hardly had + S + V3/ed + when + S + V2/ed''.'),
  ('72000000-0000-4000-c000-000000000054'::uuid, false, 'Cấu trúc câu chẻ ở hiện tại luôn bắt đầu bằng ''It is'', bất kể thành phần được nhấn mạnh là số ít hay số nhiều.'),
  ('72000000-0000-4000-c000-000000000055'::uuid, false, '''Consequently'' (do đó, kết quả là) thể hiện quan hệ nhân quả phù hợp với ngữ cảnh việc nghiên cứu bị hủy do rút vốn.'),
  ('72000000-0000-4000-c000-000000000056'::uuid, false, '''A case in point is [Noun]'' là cụm diễn đạt học thuật rất tự nhiên ở band 7.0-8.0.'),
  ('72000000-0000-4000-c000-000000000057'::uuid, false, '''However'' và ''Furthermore'' là trạng từ liên kết, cần dùng sau dấu chấm/chấm phẩy và có dấu phẩy đi kèm. ''Although'' và ''Because'' là liên từ phụ thuộc.'),
  ('72000000-0000-4000-c000-000000000058'::uuid, false, 'False. Đây là dấu hiệu của liên kết máy móc (mechanical linking), thường bị giới hạn điểm CC ở mức 6.0.'),
  ('72000000-0000-4000-c000-000000000059'::uuid, false, '''Thus'' là trạng từ ngắn gọn, rất trang trọng trong văn phong học thuật.'),
  ('72000000-0000-4000-c000-000000000060'::uuid, false, 'Cụm ''To illustrate this point'' nghĩa là ''Để minh họa cho điểm này''.'),
  ('72000000-0000-4000-c000-000000000061'::uuid, false, '''Mitigate'' có nghĩa là làm dịu bớt, làm giảm nhẹ mức độ nghiêm trọng (ví dụ: mitigate climate change).'),
  ('72000000-0000-4000-c000-000000000062'::uuid, false, '''Depletion of resources/stocks'' nghĩa là sự cạn kiệt nguồn tài nguyên.'),
  ('72000000-0000-4000-c000-000000000063'::uuid, false, 'Năng lượng mặt trời (Solar) và gió (Wind) là năng lượng tái tạo. Nhiên liệu hóa thạch và khí tự nhiên là năng lượng hữu hạn.'),
  ('72000000-0000-4000-c000-000000000064'::uuid, false, 'False. ''Biodiversity'' (đa dạng sinh học) chỉ sự phong phú của nhiều loài sinh vật khác nhau trong một hệ sinh thái.'),
  ('72000000-0000-4000-c000-000000000065'::uuid, false, '''Unsustainable'' nghĩa là không bền vững, không thể duy trì lâu dài.'),
  ('72000000-0000-4000-c000-000000000066'::uuid, false, '''Carbon footprint'' nghĩa là dấu chân carbon, lượng phát thải cá nhân.'),
  ('72000000-0000-4000-c000-000000000067'::uuid, false, '''Urban sprawl'' là thuật ngữ chỉ sự bành trướng đô thị không kiểm soát ra vùng ven.'),
  ('72000000-0000-4000-c000-000000000068'::uuid, false, '''Alleviate congestion'' nghĩa là làm giảm nhẹ tình trạng tắc nghẽn giao thông.'),
  ('72000000-0000-4000-c000-000000000069'::uuid, false, 'Mở rộng giao thông công cộng và thu phí ùn tắc nội đô (congestion charges) là 2 giải pháp tiêu chuẩn trong các bài luận IELTS.'),
  ('72000000-0000-4000-c000-000000000070'::uuid, false, 'False. ''Infrastructure'' là danh từ không đếm được. Muốn chỉ số nhiều, dùng ''infrastructure projects'' hoặc ''infrastructure systems''.'),
  ('72000000-0000-4000-c000-000000000071'::uuid, false, '''Pedestrianise'' (UK) hoặc ''pedestrianize'' (US) nghĩa là biến thành khu vực dành riêng cho người đi bộ.'),
  ('72000000-0000-4000-c000-000000000072'::uuid, false, '''Affordable housing'' nghĩa là nhà ở giá vừa túi tiền.'),
  ('72000000-0000-4000-c000-000000000073'::uuid, false, '''The digital divide'' (khoảng cách số) là thuật ngữ chỉ sự bất bình đẳng trong việc tiếp cận máy tính và internet.'),
  ('72000000-0000-4000-c000-000000000074'::uuid, false, '''Blended learning'' là phương pháp học tập kết hợp cả online và offline.'),
  ('72000000-0000-4000-c000-000000000075'::uuid, false, 'Sự thấu cảm con người (Empathy) và việc ra quyết định đạo đức phức tạp là những phẩm chất đặc trưng của con người mà AI chưa thể thay thế.'),
  ('72000000-0000-4000-c000-000000000076'::uuid, false, 'False. ''Rote learning'' là học vẹt, trái ngược với ''critical thinking'' (tư duy phản biện) và thường bị phê phán trong môi trường học thuật.'),
  ('72000000-0000-4000-c000-000000000077'::uuid, false, '''Cultivate skills'' nghĩa là nuôi dưỡng, trau dồi kỹ năng.'),
  ('72000000-0000-4000-c000-000000000078'::uuid, false, 'Artificial Intelligence nghĩa là trí tuệ nhân tạo.'),
  ('72000000-0000-4000-c000-000000000079'::uuid, false, '''Brain drain'' (chảy máu chất xám) là thuật ngữ chỉ sự thất thoát nhân lực trình độ cao.'),
  ('72000000-0000-4000-c000-000000000080'::uuid, false, '''Affluent'' là tính từ học thuật chỉ sự giàu có, khá giả (the affluent = người giàu).'),
  ('72000000-0000-4000-c000-000000000081'::uuid, false, 'Cân bằng cuộc sống - công việc tốt hơn và tiết kiệm thời gian di chuyển hàng ngày là 2 ưu điểm lớn của làm việc từ xa.'),
  ('72000000-0000-4000-c000-000000000082'::uuid, false, 'False. ''Cultural homogenisation'' là sự đồng nhất hóa, làm mất dần bản sắc riêng và khiến mọi nơi trở nên giống nhau.'),
  ('72000000-0000-4000-c000-000000000083'::uuid, false, '''Gig economy'' là nền kinh tế việc làm tự do/ngắn hạn.'),
  ('72000000-0000-4000-c000-000000000084'::uuid, false, '''Rural-urban migration'' nghĩa là sự di cư từ nông thôn ra thành thị.'),
  ('72000000-0000-4000-c000-000000000085'::uuid, false, 'Câu dùng ''allocate financial resources to the construction of educational institutions'' thay thế tự nhiên và trang trọng.'),
  ('72000000-0000-4000-c000-000000000086'::uuid, false, '''Play a pivotal/crucial role in'' là collocation học thuật chuẩn mực nghĩa là ''đóng vai trò then chốt trong...''.'),
  ('72000000-0000-4000-c000-000000000087'::uuid, false, '''Sharp increase'' tương đương ''dramatic surge'' (tăng vọt); ''drop slightly'' tương đương ''decline marginally'' (giảm nhẹ).'),
  ('72000000-0000-4000-c000-000000000088'::uuid, false, 'False. Các từ chuyên môn cốt lõi (như ''Internet'', ''students'', ''climate'') không bắt buộc phải cố tìm từ thay thế ngớ ngẩn (như đổi ''Internet'' thành ''cyberspace information superhighway'').'),
  ('72000000-0000-4000-c000-000000000089'::uuid, false, 'Danh từ của consume là ''consumption'' (sự tiêu thụ).'),
  ('72000000-0000-4000-c000-000000000090'::uuid, false, '''Detrimental effect'' nghĩa là tác động gây hại.'),
  ('72000000-0000-4000-c000-000000000091'::uuid, false, 'FALSE. Bài đọc nêu rõ chỉ lắp trên 40 mái nhà ở quận phía nam, mâu thuẫn hoàn toàn với khẳng định ''all roofs across the entire city''.'),
  ('72000000-0000-4000-c000-000000000092'::uuid, false, 'NOT GIVEN. Bài đọc chỉ cung cấp thời gian nghiên cứu (3 tháng), hoàn toàn không nhắc tới việc giáo sư có cảm thấy căng thẳng hơn dự án trước hay không.'),
  ('72000000-0000-4000-c000-000000000093'::uuid, false, '''Exclusively'' và ''Inevitably'' mang tính tuyệt đối hóa cực đoan. Nếu bài đọc chỉ dùng từ chỉ mức độ vừa phải, câu nhận định này thường là False.'),
  ('72000000-0000-4000-c000-000000000094'::uuid, false, 'False. Bài thi IELTS chỉ chấm điểm dựa trên thông tin có trong văn bản (according to the text). Kiến thức bên ngoài không có giá trị nếu bài đọc không đề cập.'),
  ('72000000-0000-4000-c000-000000000095'::uuid, false, 'Thiếu vế so sánh trong bài đọc thì nhận định là NOT GIVEN.'),
  ('72000000-0000-4000-c000-000000000096'::uuid, false, 'Có. Quy chế thi khuyên thí sinh viết đúng format YES/NO/NOT GIVEN theo yêu cầu của đề để tránh tranh chấp quy chuẩn chấm điểm.'),
  ('72000000-0000-4000-c000-000000000097'::uuid, false, 'Các đoạn văn học thuật tiếng Anh thường phát triển theo cấu trúc diễn dịch, câu chủ đề nằm ở câu 1 hoặc 2 của đoạn.'),
  ('72000000-0000-4000-c000-000000000098'::uuid, false, 'Đây là bẫy kinh điển. Tiêu đề phải bao quát toàn đoạn chứ không phải tóm tắt một ví dụ nhỏ.'),
  ('72000000-0000-4000-c000-000000000099'::uuid, false, 'Đọc qua danh sách tiêu đề và gạch chân từ khóa phân biệt giúp bạn định hướng trước khi đọc vào bài đọc.'),
  ('72000000-0000-4000-c000-000000000100'::uuid, false, 'False. Mỗi đoạn văn chỉ có DUY NHẤT một tiêu đề chính xác nhất. Số lượng tiêu đề trong danh sách luôn nhiều hơn số lượng đoạn văn (để làm bẫy nhiễu).'),
  ('72000000-0000-4000-c000-000000000101'::uuid, false, 'Topic sentence là câu chủ đề của đoạn.'),
  ('72000000-0000-4000-c000-000000000102'::uuid, false, 'Luôn có các tiêu đề thừa làm nhiệm vụ gây nhiễu (distractors).'),
  ('72000000-0000-4000-c000-000000000103'::uuid, false, 'Tuesday chỉ là dự định ban đầu, vé hết nên đã chuyển sang đặt vé ngày Wednesday. Wednesday là đáp án đúng.'),
  ('72000000-0000-4000-c000-000000000104'::uuid, false, '''Actually'' hoặc ''In fact'' là từ nối điển hình báo hiệu việc đính chính sự thật hoặc sửa đổi thông tin.'),
  ('72000000-0000-4000-c000-000000000105'::uuid, false, 'Kiểm tra giới hạn số từ (Word limit) và dự đoán loại từ là 2 thao tác sống còn trong IELTS Listening.'),
  ('72000000-0000-4000-c000-000000000106'::uuid, false, 'False. ''Two cars'' gồm 2 từ (''two'' là chữ số viết bằng chữ + ''cars''), vi phạm quy tắc ''NO MORE THAN ONE WORD''. Viết ''2 cars'' mới hợp lệ (1 number + 1 word).'),
  ('72000000-0000-4000-c000-000000000107'::uuid, false, 'Người bản xứ thường đọc là ''double zero'' hoặc ''double oh''.'),
  ('72000000-0000-4000-c000-000000000108'::uuid, false, 'Không. Lỗi sai chính tả dù chỉ 1 ký tự trong IELTS Listening đều bị tính là 0 điểm.'),
  ('72000000-0000-4000-c000-000000000109'::uuid, false, 'E thứ nhất là Explanation - giải thích tại sao luận điểm đó lại đúng và dẫn đến hệ quả gì.'),
  ('72000000-0000-4000-c000-000000000110'::uuid, false, 'Liệt kê ý mà thiếu phát triển chiều sâu là đặc trưng của Band 5.0-5.5 (''presents some main ideas but these are limited and not sufficiently developed'').'),
  ('72000000-0000-4000-c000-000000000111'::uuid, false, 'Opinion và Discussion là 2 dạng đề Task 2 phổ biến nhất. Viết thư là Task 1 General, mô tả quy trình là Task 1 Academic.'),
  ('72000000-0000-4000-c000-000000000112'::uuid, false, 'True. Viết dưới 250 từ sẽ bị phạt điểm Task Response vì không phát triển đủ độ dài yêu cầu.'),
  ('72000000-0000-4000-c000-000000000113'::uuid, false, 'Độ dài tối thiểu là 250 từ (khuyến nghị viết từ 260 - 290 từ).'),
  ('72000000-0000-4000-c000-000000000114'::uuid, false, 'Khuyến nghị phân bổ 40 phút cho Task 2 và 20 phút cho Task 1.'),
  ('72000000-0000-4000-c000-000000000115'::uuid, false, 'Trong Part 1, 2-4 câu là độ dài vừa vặn nhất, vừa đủ ý vừa không biến thành bài diễn thuyết đơn điệu.'),
  ('72000000-0000-4000-c000-000000000116'::uuid, false, '''Well, that''s an interesting question...'' giúp người nói có thêm thời gian sắp xếp ý tưởng mà không làm đứt gãy luồng nói.'),
  ('72000000-0000-4000-c000-000000000117'::uuid, false, '4 tiêu chí Speaking gồm: Fluency and Coherence, Lexical Resource, Grammatical Range and Accuracy, và Pronunciation. Cử chỉ tay không được tính điểm.'),
  ('72000000-0000-4000-c000-000000000118'::uuid, false, 'True. Part 2 luôn dành cho thí sinh đúng 1 phút chuẩn bị và phát giấy bút để ghi chú (take notes).'),
  ('72000000-0000-4000-c000-000000000119'::uuid, false, 'Speaking Part 2 yêu cầu nói từ 1 đến 2 phút (tối ưu là nói cho đến khi giám khảo ra hiệu dừng ở mốc 2 phút).'),
  ('72000000-0000-4000-c000-000000000120'::uuid, false, 'A cuối cùng là Alternative (ý kiến mở rộng hoặc trường hợp ngoại lệ).')
