  ('10000000-0000-4000-c000-000000000001'::uuid, 'ielts-foundations', 'IELTS Foundations & Test Architecture', 'Nắm vững toàn diện cấu trúc 4 kỹ năng bài thi IELTS, tiêu chí chấm điểm Cambridge, kỹ thuật làm bài thi trên máy và phương pháp ghi nhận lỗi sai chủ động.', 'foundations', 'both', 'beginner', 1, 'published', 120, '2026-10-25T00:00:00Z'),
  ('10000000-0000-4000-c000-000000000002'::uuid, 'academic-grammar', 'Academic Grammar Mastery', 'Làm chủ ngữ pháp học thuật trọng điểm: sự hòa hợp chủ-vị phức tạp, câu ghép-câu phức, mệnh đề quan hệ rút gọn, thể bị động học thuật, đảo ngữ và phương tiện liên kết Cohesion.', 'grammar', 'academic', 'intermediate', 2, 'published', 150, '2026-10-25T00:00:00Z'),
  ('10000000-0000-4000-c000-000000000003'::uuid, 'academic-vocabulary', 'Essential Academic Vocabulary & Collocations', 'Bộ từ vựng học thuật C1/C2 theo 4 chủ đề lớn: Môi trường & Khí hậu, Đô thị & Công nghệ, Giáo dục & Việc làm, Xã hội toàn cầu hóa, kèm các cặp Collocations ăn điểm Lexical Resource.', 'vocabulary', 'academic', 'intermediate', 3, 'published', 150, '2026-10-25T00:00:00Z'),
  ('10000000-0000-4000-c000-000000000004'::uuid, 'core-strategies', 'Core Exam Strategies & Trap Avoidance', 'Chiến thuật thực chiến đỉnh cao: Giải mã bẫy True/False/Not Given, Matching Headings, nhận diện Paraphrase trong Listening, tư duy phát triển ý Writing Task 2 và phản xạ lưu loát Speaking.', 'foundations', 'academic', 'advanced', 4, 'published', 140, '2026-10-25T00:00:00Z')
