  ('30000000-0000-4000-c000-000000000001'::uuid, '20000000-0000-4000-c000-000000000001'::uuid, 1, 'Cấu trúc 4 kỹ năng & Tiêu chuẩn chấm điểm Cambridge IELTS', 'Hiểu rõ format từng kỹ năng thi, số lượng câu hỏi, thời gian quy định và sự khác biệt giữa Academic và General Training.', 'beginner', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000002'::uuid, '20000000-0000-4000-c000-000000000002'::uuid, 1, 'Phân tích Band Descriptors (Từ 5.0 lên 7.0+ cần gì?)', 'Bóc tách 4 tiêu chí chấm điểm Writing và Speaking: Task Achievement/Response, Coherence & Cohesion, Lexical Resource, và Grammatical Range & Accuracy.', 'beginner', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000003'::uuid, '20000000-0000-4000-c000-000000000003'::uuid, 1, 'Quản lý thời gian thi máy (Computer-delivered IELTS)', 'Nắm vững kỹ thuật thao tác trên giao diện thi máy: highlight, note, split-screen, phím tắt và chiến thuật chia thời gian 20-40 phút.', 'beginner', 20, 'draft', null),
  ('30000000-0000-4000-c000-000000000004'::uuid, '20000000-0000-4000-c000-000000000004'::uuid, 1, 'Kỹ thuật ghi chép và kiểm soát lỗi sai (Active Error-Logging)', 'Xây dựng sổ tay lỗi sai cá nhân hóa: phân loại lỗi do từ vựng, ngữ pháp, bẫy logic hay bất cẩn để chặn đứng việc lặp lại lỗi sai.', 'beginner', 20, 'draft', null),
  ('30000000-0000-4000-c000-000000000005'::uuid, '20000000-0000-4000-c000-000000000005'::uuid, 1, 'Chiến lược đọc lướt định vị (Skimming & Scanning Protocol)', 'Phân biệt rõ ràng giữa Skimming (đọc nắm ý chính cấu trúc) và Scanning (quét tìm định vị dữ liệu cụ thể) để tối ưu tốc độ đọc hiểu.', 'beginner', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000006'::uuid, '20000000-0000-4000-c000-000000000006'::uuid, 1, 'Sự hòa hợp Chủ ngữ - Động từ trong cấu trúc phức tạp', 'Xác định chính xác danh từ trung tâm (head noun) khi có cụm giới từ chen ngang, đại từ bất định và cấu trúc ''The number of'' vs ''A number of''.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000007'::uuid, '20000000-0000-4000-c000-000000000007'::uuid, 1, 'Kiểm soát câu phức và Mệnh đề quan hệ (Complex Sentences)', 'Xây dựng các câu phức học thuật chuẩn xác bằng mệnh đề quan hệ xác định/không xác định, mệnh đề trạng ngữ chỉ sự nhượng bộ và nguyên nhân.', 'intermediate', 30, 'draft', null),
  ('30000000-0000-4000-c000-000000000008'::uuid, '20000000-0000-4000-c000-000000000008'::uuid, 1, 'Thể bị động học thuật và Kỹ thuật Hedging', 'Tạo lập giọng văn khách quan, trang trọng bằng Passive Voice khách quan và kỹ thuật ngôn ngữ cẩn trọng (Hedging) tránh khẳng định tuyệt đối.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000009'::uuid, '20000000-0000-4000-c000-000000000009'::uuid, 1, 'Đảo ngữ và Cấu trúc nhấn mạnh C1/C2 (Inversion & Cleft Sentences)', 'Nâng band điểm Grammatical Range với cấu trúc đảo ngữ với trạng từ phủ định (Not only, Rarely, Under no circumstances) và câu chẻ (It is... that...).', 'advanced', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000010'::uuid, '20000000-0000-4000-c000-000000000010'::uuid, 1, 'Phương tiện liên kết đoạn Cohesive Devices & Discourse Markers', 'Nâng cao điểm số Coherence & Cohesion bằng cách sử dụng linh hoạt các liên từ chỉ nguyên nhân, hệ quả, bổ sung và tương phản thay vì lặp lại ''Furthermore'' và ''Moreover''.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000011'::uuid, '20000000-0000-4000-c000-000000000011'::uuid, 1, 'Từ vựng Chủ đề Môi trường & Biến đổi khí hậu', 'Nạp bộ từ vựng và Collocations C1/C2 chủ đề Environmental Degradation, Renewable Energy, Biodiversity Loss và Carbon Footprint.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000012'::uuid, '20000000-0000-4000-c000-000000000012'::uuid, 1, 'Từ vựng Chủ đề Đô thị hóa, Giao thông & Nhà ở', 'Trang bị các thuật ngữ học thuật về quy hoạch đô thị: Urban Sprawl, Traffic Congestion, Affordable Housing và Pedestrianisation.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000013'::uuid, '20000000-0000-4000-c000-000000000013'::uuid, 1, 'Từ vựng Chủ đề Giáo dục, AI & Công nghệ', 'Vốn từ học thuật về chuyển đổi số trong giáo dục: Artificial Intelligence, Algorithmic Bias, Digital Literacy và Blended Learning.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000014'::uuid, '20000000-0000-4000-c000-000000000014'::uuid, 1, 'Từ vựng Chủ đề Xã hội, Việc làm & Toàn cầu hóa', 'Nắm vững bộ từ vựng về thị trường lao động hiện đại: Gig Economy, Automation, Wealth Disparity và Cultural Homogenisation.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000015'::uuid, '20000000-0000-4000-c000-000000000015'::uuid, 1, 'Academic Collocations & Paraphrase linh hoạt', 'Rèn luyện nghệ thuật Paraphrase 4 cấp độ (từ đồng nghĩa, biến đổi từ loại, chuyển thể chủ động/bị động, đổi cấu trúc câu) để bứt phá band 7.0+.', 'intermediate', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000016'::uuid, '20000000-0000-4000-c000-000000000016'::uuid, 1, 'Bóc tách bẫy logic True / False / Not Given trong Reading', 'Quy tắc bất biến phân biệt giữa False (thông tin mâu thuẫn trực tiếp) và Not Given (thông tin không đề cập hoặc thiếu cơ sở so sánh).', 'advanced', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000017'::uuid, '20000000-0000-4000-c000-000000000017'::uuid, 1, 'Chiến thuật xử lý Matching Headings & Bẫy tiêu đề', 'Kỹ thuật định vị Topic Sentence, bóc tách cấu trúc đoạn văn và loại bỏ bẫy tiêu đề chỉ chứa chi tiết phụ.', 'advanced', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000018'::uuid, '20000000-0000-4000-c000-000000000018'::uuid, 1, 'Nhận diện Distractors và Paraphrase trong Listening Section 1-3', 'Bắt trọn tín hiệu người nói tự đính chính thông tin (Self-correction), nhận diện bẫy số nhiều/số ít và từ gây nhiễu trong bài nghe.', 'advanced', 25, 'draft', null),
  ('30000000-0000-4000-c000-000000000019'::uuid, '20000000-0000-4000-c000-000000000019'::uuid, 1, 'Tư duy lập dàn ý và Phát triển luận điểm Writing Task 2 (PEEL paragraph)', 'Xây dựng thân bài chuẩn cấu trúc PEEL (Point - Explanation - Example - Link) để đạt điểm tuyệt đối về tính phát triển ý trong Task Response.', 'advanced', 30, 'draft', null),
  ('30000000-0000-4000-c000-000000000020'::uuid, '20000000-0000-4000-c000-000000000020'::uuid, 1, 'Phản xạ mở rộng câu trả lời và Duy trì Fluency Speaking', 'Công thức kéo dài câu trả lời tự nhiên cho Speaking Part 1 & Part 2 bằng quy tắc AREA (Answer, Reason, Example, Alternative) và kỹ thuật câu giờ thông minh.', 'advanced', 25, 'draft', null)
on conflict (id) do nothing;

-- 4. Ingest Lesson Sections
  id, lesson_version_id, section_type, title, body_markdown, display_order, is_required
) values
  ('40000000-0000-4000-c000-000000000001'::uuid, '30000000-0000-4000-c000-000000000001'::uuid, 'text', 'Tổng quan cấu trúc bài thi IELTS chuẩn quốc tế', 'Bài thi IELTS bao gồm 4 kỹ năng bắt buộc: **Listening (30 phút + 10 phút chuyển đáp án hoặc 2 phút kiểm tra trên máy)**, **Reading (60 phút - 40 câu)**, **Writing (60 phút - 2 Tasks)**, và **Speaking (11-14 phút)**. Điểm tổng (Overall Band Score) là trung bình cộng của 4 kỹ năng, làm tròn tới 0.5 gần nhất.

Trong bài thi Academic, phần Reading bao gồm 3 bài đọc học thuật dài với tổng cộng 40 câu hỏi, trong khi Writing gồm Task 1 (báo cáo dữ liệu đồ thị) và Task 2 (bài luận nghị luận xã hội).', 1, true),
  ('40000000-0000-4000-c000-000000000002'::uuid, '30000000-0000-4000-c000-000000000001'::uuid, 'example', 'Quy tắc làm tròn điểm Overall', '- Nghe: 6.5, Đọc: 6.5, Viết: 6.0, Nói: 6.0 → Trung bình: 6.25 → Làm tròn lên **Band 6.5**.
- Nghe: 6.5, Đọc: 6.0, Viết: 6.0, Nói: 6.0 → Trung bình: 6.125 → Làm tròn xuống **Band 6.0**.
- Nghe: 7.0, Đọc: 7.5, Viết: 6.5, Nói: 6.0 → Trung bình: 6.75 → Làm tròn lên **Band 7.0**.', 2, true),
  ('40000000-0000-4000-c000-000000000003'::uuid, '30000000-0000-4000-c000-000000000001'::uuid, 'checklist', 'Quy tắc vàng trước khi bắt đầu luyện thi', '1. Xác định chính xác mục tiêu: Academic (du học, nghiên cứu) hay General Training (định cư, việc làm).
2. Ghi nhớ thời gian thi từng phần: Listening và Reading không có giải lao giữa giờ.
3. Đối với bài thi máy tính (Computer-delivered), thời gian đọc và kiểm tra đáp án khác với bài thi giấy.', 3, true),
  ('40000000-0000-4000-c000-000000000004'::uuid, '30000000-0000-4000-c000-000000000002'::uuid, 'text', 'Bản chất của 4 tiêu chí chấm điểm IELTS chính thức', 'Giám khảo IELTS chấm điểm Writing và Speaking dựa trên bảng tiêu chí công khai (Band Descriptors):
- **Task Achievement (Task 1) / Task Response (Task 2)**: Trả lời đầy đủ các phần của đề bài, có lập trường rõ ràng xuyên suốt.
- **Coherence & Cohesion (CC)**: Bố cục đoạn hợp lý, ý tưởng phát triển tuần tự, sử dụng liên từ tự nhiên không gượng ép.
- **Lexical Resource (LR)**: Vốn từ rộng, dùng từ ngữ học thuật chính xác theo ngữ cảnh, có collocations và nhận thức về phong cách trang trọng.
- **Grammatical Range & Accuracy (GRA)**: Sử dụng linh hoạt nhiều kiểu câu (đơn, ghép, phức) với tỉ lệ câu không mắc lỗi cao.', 1, true),
  ('40000000-0000-4000-c000-000000000005'::uuid, '30000000-0000-4000-c000-000000000002'::uuid, 'example', 'Sự khác biệt giữa Band 6.0 và Band 7.0 trong tiêu chí Lexical Resource', '- **Band 6.0**: Sử dụng vốn từ đủ để diễn đạt ý nhưng còn lặp từ, thỉnh thoảng dùng collocations sai ngữ cảnh hoặc mắc lỗi chính tả nhỏ không cản trở thông điệp.
- **Band 7.0**: Sử dụng linh hoạt các từ vựng ít phổ biến (less common vocabulary), nắm chắc phong cách diễn đạt và collocations, hiếm khi mắc lỗi lựa chọn từ.', 2, true),
  ('40000000-0000-4000-c000-000000000006'::uuid, '30000000-0000-4000-c000-000000000002'::uuid, 'tip', 'Cách tối ưu điểm Grammatical Range', 'Để đạt Band 7.0+ GRA, bạn không cần phải cố viết toàn những câu cực dài 50 từ. Điều quan trọng là sự đa dạng cấu trúc (mệnh đề quan hệ, thể bị động, câu điều kiện, cấu trúc đảo ngữ) và bảo đảm hơn 50% số câu hoàn toàn không có lỗi ngữ pháp (error-free sentences).', 3, true),
  ('40000000-0000-4000-c000-000000000007'::uuid, '30000000-0000-4000-c000-000000000003'::uuid, 'text', 'Lợi thế và thách thức khi thi IELTS trên máy tính', 'Thi IELTS trên máy tính ngày càng phổ biến nhờ kết quả nhanh (1-5 ngày) và tai nghe riêng biệt. Tuy nhiên, thí sinh phải làm quen với việc đọc trên màn hình máy tính liên tục 60 phút và kỹ năng gõ phím.

Trong phần Reading, giao diện chia làm 2 cột: Cột trái là văn bản bài đọc, cột phải là phiếu câu hỏi. Bạn có thể bôi đen (highlight) và thêm ghi chú (note) trực tiếp trên văn bản.', 1, true),
  ('40000000-0000-4000-c000-000000000008'::uuid, '30000000-0000-4000-c000-000000000003'::uuid, 'example', 'Quy tắc phân bổ thời gian chuẩn trong IELTS Reading', '- **Passage 1**: 15 - 17 phút (Dạng bài dễ nhất, mục tiêu lấy trọn điểm).
- **Passage 2**: 20 phút (Độ khó trung bình, chủ đề nghiên cứu hoặc sự kiện văn hóa).
- **Passage 3**: 23 - 25 phút (Bài đọc học thuật trừu tượng nhất, lập luận phức tạp).
- Tuyệt đối không dành quá 20 phút cho Passage 1 khiến Passage 3 không kịp làm bài.', 2, true),
  ('40000000-0000-4000-c000-000000000009'::uuid, '30000000-0000-4000-c000-000000000003'::uuid, 'checklist', 'Checklist phím tắt và thao tác trên máy', '1. `Ctrl + C` và `Ctrl + V` dùng được trong bài thi Writing.
2. Phím `Tab` để di chuyển nhanh giữa các ô điền từ trong Listening và Reading.
3. Nhấp chuột phải để Highlight từ khóa và chọn Note để ghi chú ý nghĩa.', 3, true),
  ('40000000-0000-4000-c000-000000000010'::uuid, '30000000-0000-4000-c000-000000000004'::uuid, 'text', 'Vì sao luyện nhiều đề không tăng điểm nếu thiếu Error Log?', 'Nhiều người học làm hàng chục bộ đề Cam nhưng điểm số vẫn giậm chân tại chỗ. Lý do là họ chỉ chấm điểm lấy số đúng mà không phân tích nguyên nhân vì sao sai. Phương pháp **Active Error-Logging** yêu cầu bạn ghi lại mọi câu sai vào sổ tay với 4 thông tin bắt buộc:
1. Câu hỏi và đáp án bạn đã chọn.
2. Đáp án đúng của bài.
3. Bằng chứng trích xuất từ bài đọc/bài nghe (Evidence).
4. Phân loại nguyên nhân sai (Error Taxonomy).', 1, true),
  ('40000000-0000-4000-c000-000000000011'::uuid, '30000000-0000-4000-c000-000000000004'::uuid, 'example', 'Bảng phân loại nguyên nhân sai chuẩn Cambridge', '- **Lỗi từ vựng (Vocabulary Gap)**: Không biết nghĩa của từ hoặc từ bị paraphrase.
- **Lỗi bẫy logic (Logic / Trap)**: Nhầm lẫn giữa False (thông tin mâu thuẫn) và Not Given (thông tin không đề cập).
- **Lỗi chính tả/Ngữ pháp (Spelling/Grammar)**: Quên thêm số nhiều `-s`, viết sai chính tả từ quen thuộc.
- **Lỗi định vị (Locating Failure)**: Tìm sai đoạn văn chứa thông tin do bám vào từ khóa bẫy.', 2, true),
  ('40000000-0000-4000-c000-000000000012'::uuid, '30000000-0000-4000-c000-000000000004'::uuid, 'tip', 'Quy tắc 24 giờ xem lại', 'Sau khi ghi nhận một câu sai vào Sổ tay lỗi sai (Error Notebook), hãy đặt lịch làm lại đúng câu hỏi đó sau 24-48 giờ mà không nhìn vào đáp án. Nếu bạn giải thích được bằng chứng tại sao đáp án đó đúng, bạn đã thực sự làm chủ kiến thức.', 3, true),
  ('40000000-0000-4000-c000-000000000013'::uuid, '30000000-0000-4000-c000-000000000005'::uuid, 'text', 'Bản chất của Skimming vs Scanning', '- **Skimming (Đọc lướt)**: Là kỹ thuật đọc nhanh với tốc độ 300-400 từ/phút nhằm nắm được chủ đề tổng quan, cấu trúc phát triển của văn bản và ý chính của từng đoạn (thường nằm ở Topic Sentence - câu đầu hoặc câu cuối đoạn).
- **Scanning (Đọc quét)**: Là thao tác di chuyển mắt có định hướng để tìm kiếm các dữ liệu cụ thể như tên riêng, con số, mốc năm, thuật ngữ viết hoa hoặc từ đồng nghĩa với câu hỏi mà không cần đọc hiểu toàn bộ câu xung quanh.', 1, true),
  ('40000000-0000-4000-c000-000000000014'::uuid, '30000000-0000-4000-c000-000000000005'::uuid, 'example', 'Khi nào dùng Skimming, khi nào dùng Scanning?', '- **Dùng Skimming**: Cho dạng bài *Matching Headings* (Nối tiêu đề đoạn) hoặc *Main Idea* (Ý chính của bài viết).
- **Dùng Scanning**: Cho dạng bài *Sentence Completion* (Điền từ), *Short Answer Questions* hoặc *Table/Flowchart Completion* nơi bạn cần tìm chính xác một dữ liệu cụ thể.', 2, true),
  ('40000000-0000-4000-c000-000000000015'::uuid, '30000000-0000-4000-c000-000000000005'::uuid, 'warning', 'Cảnh báo bẫy trùng khớp từ vựng (Word-matching trap)', 'Trong IELTS Reading, câu chứa từ khóa trùng khớp 100% với đề bài thường là **BẪY**. Đáp án đúng hầu như luôn được diễn đạt bằng **Paraphrase** (từ đồng nghĩa hoặc thay đổi cấu trúc ngữ pháp). Đừng vội chọn đáp án chỉ vì thấy có từ y hệt trong đề!', 3, true),
  ('40000000-0000-4000-c000-000000000016'::uuid, '30000000-0000-4000-c000-000000000006'::uuid, 'text', 'Quy tắc cốt lõi: Tìm Head Noun thực sự của chủ ngữ', 'Lỗi hòa hợp chủ-vị (Subject-Verb Agreement - SVA) là lỗi mất điểm phổ biến nhất trong IELTS Writing và Speaking ở band 5.0-6.0. Nguyên nhân chính là người học bị đánh lừa bởi các cụm từ nằm giữa chủ ngữ chính và động từ.

**Quy tắc:** Hãy loại bỏ các thành phần bổ nghĩa (cụm giới từ, mệnh đề quan hệ rút gọn) để tìm ra **Head Noun** (danh từ trung tâm).', 1, true),
  ('40000000-0000-4000-c000-000000000017'::uuid, '30000000-0000-4000-c000-000000000006'::uuid, 'example', 'Ví dụ kinh điển về Head Noun', '- *Câu sai:* The quality of the urban public transport systems have improved.
- *Phân tích:* Danh từ trung tâm là **The quality** (số ít), cụm ''of the urban public transport systems'' chỉ là bổ ngữ giới từ.
- *Câu đúng:* The quality of the urban public transport systems **has** improved.', 2, true),
  ('40000000-0000-4000-c000-000000000018'::uuid, '30000000-0000-4000-c000-000000000006'::uuid, 'tip', 'Phân biệt ''The number of'' vs ''A number of''', '- **The number of + N(số nhiều) + V(số ít)**: Nhấn mạnh vào con số (The number is increasing).
- **A number of + N(số nhiều) + V(số nhiều)**: Đồng nghĩa với ''many / several'' (A number of students are participating).', 3, true),
  ('40000000-0000-4000-c000-000000000019'::uuid, '30000000-0000-4000-c000-000000000007'::uuid, 'text', 'Bản chất câu phức trong tiêu chí Grammatical Range', 'Để đạt Band 6.0+ tiêu chí Ngữ pháp, bài viết bắt buộc phải có sự kết hợp linh hoạt giữa câu đơn, câu ghép và câu phức. Một câu phức (Complex Sentence) bao gồm **một mệnh đề độc lập (Independent Clause)** và **ít nhất một mệnh đề phụ thuộc (Dependent Clause)** bắt đầu bằng các liên từ phụ thuộc như *although, because, while, whereas, since* hoặc đại từ quan hệ *which, who, that*.', 1, true),
  ('40000000-0000-4000-c000-000000000020'::uuid, '30000000-0000-4000-c000-000000000007'::uuid, 'example', 'Ví dụ chuyển đổi câu đơn sang câu phức học thuật', '- *2 câu đơn:* Renewable energy is expensive initially. It reduces carbon emissions substantially.
- *Câu phức dùng Although:* **Although** renewable energy requires substantial initial capital investment, it provides considerable long-term environmental benefits.
- *Câu phức dùng Mệnh đề quan hệ:* Governments should subsidise green energy sources, **which** can drastically accelerate the transition to sustainable economies.', 2, true),
  ('40000000-0000-4000-c000-000000000021'::uuid, '30000000-0000-4000-c000-000000000007'::uuid, 'warning', 'Tránh lỗi Run-on Sentences và Comma Splices', 'Lỗi Comma Splice xảy ra khi nối hai mệnh đề độc lập chỉ bằng một dấu phẩy mà không có liên từ kết hợp (FANBOYS: for, and, nor, but, or, yet, so).
- *Sai:* The project was delayed, the budget was insufficient.
- *Đúng:* The project was delayed **because** the budget was insufficient. HOẶC: The project was delayed**;** the budget was insufficient.', 3, true),
  ('40000000-0000-4000-c000-000000000022'::uuid, '30000000-0000-4000-c000-000000000008'::uuid, 'text', 'Vai trò của Thể bị động và Hedging trong văn phong IELTS', 'Trong bài viết IELTS Academic, thí sinh thường bị trừ điểm Task Response và Lexical Resource khi đưa ra các nhận định mang tính tuyệt đối hóa như *''Everyone knows that...''* hoặc *''Technology always causes unemployment.''*.

Để đạt tính học thuật cao, bạn cần sử dụng:
1. **Thể bị động khách quan (Impersonal Passive)**: Giấu chủ thể cá nhân, tập trung vào hiện tượng.
2. **Kỹ thuật Hedging (Ngôn ngữ cẩn trọng)**: Sử dụng các động từ khuyết thiếu (modal verbs: *may, could, tend to*) và trạng từ chỉ khả năng (*presumably, arguably, likely*).', 1, true),
  ('40000000-0000-4000-c000-000000000023'::uuid, '30000000-0000-4000-c000-000000000008'::uuid, 'example', 'Ví dụ so sánh câu tuyệt đối hóa vs câu có Hedging', '- *Tuyệt đối hóa (Kém học thuật):* Excessive screen time destroys children''s mental development.
- *Có Hedging học thuật:* Excessive screen time **is widely believed to have a detrimental effect on** children''s cognitive development, **potentially leading to** attention deficits.
- *Thể bị động khách quan:* **It is often asserted that** remote learning cannot fully replace traditional classroom instruction.', 2, true),
  ('40000000-0000-4000-c000-000000000024'::uuid, '30000000-0000-4000-c000-000000000008'::uuid, 'tip', 'Công thức Impersonal Passive kinh điển', '- `It is widely acknowledged / contended / argued that + Clause`
- `X is considered / deemed / believed to be + Adjective/Noun`', 3, true),
  ('40000000-0000-4000-c000-000000000025'::uuid, '30000000-0000-4000-c000-000000000009'::uuid, 'text', 'Sức mạnh của Inversion và Cleft Sentences trong bài luận', 'Để gây ấn tượng với giám khảo ở tiêu chí Grammatical Range (Band 7.5 - 8.5), việc đưa vào 1-2 cấu trúc nhấn mạnh đúng ngữ cảnh sẽ chứng minh bạn làm chủ cấu trúc câu nâng cao.

1. **Đảo ngữ với trạng từ phủ định/bán phủ định**: Khi đặt các từ như *Not only, Seldom, Rarely, Hardly, Under no circumstances* lên đầu câu, trật tự từ bị đảo giống như câu hỏi (Trợ động từ + Chủ ngữ + Động từ chính).
2. **Câu chẻ (Cleft Sentence)**: `It is/was + Thành phần nhấn mạnh + that/who + Mệnh đề`.', 1, true),
  ('40000000-0000-4000-c000-000000000026'::uuid, '30000000-0000-4000-c000-000000000009'::uuid, 'example', 'Ví dụ câu đảo ngữ chuẩn mực', '- *Câu thường:* Automation not only boosts productivity, but it also creates high-skilled jobs.
- *Câu đảo ngữ:* **Not only does automation boost** industrial productivity, **but it also fosters** the emergence of novel high-skilled occupations.
- *Câu chẻ:* **It is the government that** must assume primary responsibility for infrastructure upgrades.', 2, true),
  ('40000000-0000-4000-c000-000000000027'::uuid, '30000000-0000-4000-c000-000000000009'::uuid, 'warning', 'Không lạm dụng đảo ngữ gượng ép', 'Chỉ nên dùng tối đa 1 câu đảo ngữ trong toàn bộ bài viết Task 2, thường là ở câu mở rộng luận điểm hoặc phần kết bài. Lạm dụng 3-4 câu đảo ngữ sẽ làm bài viết trở nên kịch tính hóa (melodramatic) và mất đi vẻ tự nhiên học thuật.', 3, true),
  ('40000000-0000-4000-c000-000000000028'::uuid, '30000000-0000-4000-c000-000000000010'::uuid, 'text', 'Bẫy ''Mechanical Linking'' trong tiêu chí Cohesion', 'Bảng Band Descriptors nêu rõ rằng thí sinh Band 6.0 thường mắc lỗi **''mechanical linking''** (sử dụng liên từ một cách máy móc: câu nào cũng mở đầu bằng *Firstly, Secondly, Furthermore, In addition, In conclusion*).

Để đạt Band 7.0-8.0 CC, bạn cần sử dụng liên kết tự nhiên thông qua đại từ thay thế (*this phenomenon, these measures*), danh từ hóa (Nominalization), và đặt trạng từ liên kết vào giữa câu thay vì luôn đặt ở đầu câu.', 1, true),
  ('40000000-0000-4000-c000-000000000029'::uuid, '30000000-0000-4000-c000-000000000010'::uuid, 'example', 'Kỹ thuật đặt liên từ linh hoạt vào giữa câu', '- *Cách viết thông thường (Band 6):* Public transport is heavily subsidized. **However**, many residents still prefer private cars.
- *Cách viết linh hoạt (Band 7+):* Public transport is heavily subsidized; many residents, **however**, continue to rely on private vehicles.
- *Liên kết bằng danh từ thay thế:* The government recently introduced congestion charges. **This policy** has proven effective in mitigating peak-hour bottlenecks.', 2, true),
  ('40000000-0000-4000-c000-000000000030'::uuid, '30000000-0000-4000-c000-000000000010'::uuid, 'checklist', 'Bảng từ vựng liên kết học thuật thay thế', '1. Thay cho ''Therefore'': *Consequently, As a consequence, Hence, Thus*.
2. Thay cho ''Furthermore'': *Moreover, Additionally, What is more*.
3. Thay cho ''For example'': *For instance, To illustrate this point, A case in point is...*.', 3, true),
  ('40000000-0000-4000-c000-000000000031'::uuid, '30000000-0000-4000-c000-000000000011'::uuid, 'text', 'Bộ từ vựng cốt lõi Chủ đề Môi trường', 'Môi trường là một trong những chủ đề xuất hiện với tần suất cao nhất trong cả 4 kỹ năng thi IELTS. Thay vì dùng các từ đơn giản như *pollution, dirty, save animals*, bạn cần sử dụng các thuật ngữ chuyên sâu:
- **Ecological degradation**: Sự suy thoái hệ sinh thái.
- **Carbon-neutral economy**: Nền kinh tế trung hòa carbon.
- **Habitat fragmentation**: Sự phân mảnh môi trường sống của động vật.
- **Depletion of natural resources**: Sự cạn kiệt tài nguyên thiên nhiên.', 1, true),
  ('40000000-0000-4000-c000-000000000032'::uuid, '30000000-0000-4000-c000-000000000011'::uuid, 'example', 'Các Collocations đắt giá chủ đề Môi trường', '- **To mitigate the catastrophic impacts of climate change**: Giảm thiểu các tác động thảm khốc của biến đổi khí hậu.
- **To transition to renewable energy sources**: Chuyển đổi sang các nguồn năng lượng tái tạo.
- **Irreversible environmental damage**: Thiệt hại môi trường không thể phục hồi.
- **Unsustainable consumption patterns**: Mô hình tiêu thụ không bền vững.', 2, true),
  ('40000000-0000-4000-c000-000000000033'::uuid, '30000000-0000-4000-c000-000000000011'::uuid, 'tip', 'Ứng dụng vào đề Writing Task 2', 'Ví dụ mở bài: *''The relentless expansion of industrial activities has precipitated severe ecological degradation, prompting urgent debate over whether governments or individuals should bear primary accountability.''*', 3, true),
  ('40000000-0000-4000-c000-000000000034'::uuid, '30000000-0000-4000-c000-000000000012'::uuid, 'text', 'Từ vựng trọng tâm về Quy hoạch & Đô thị hóa', 'Đô thị hóa (Urbanisation) gắn liền với các vấn đề xã hội như quá tải hạ tầng, giá nhà leo thang và ô nhiễm tiếng ồn. Các thuật ngữ quan trọng:
- **Urban sprawl**: Sự mở rộng đô thị thiếu kiểm soát ra vùng ven.
- **High-density residential development**: Phát triển khu dân cư mật độ cao (chung cư cao tầng).
- **Integrated public transit network**: Mạng lưới giao thông công cộng tích hợp (tàu điện ngầm kết nối xe bus).
- **Pedestrianisation**: Quy hoạch phố đi bộ, cấm phương tiện cơ giới.', 1, true),
  ('40000000-0000-4000-c000-000000000035'::uuid, '30000000-0000-4000-c000-000000000012'::uuid, 'example', 'Collocations hữu ích cho đề bài Urban Living', '- **To alleviate chronic traffic congestion**: Giảm bớt tắc nghẽn giao thông kinh niên.
- **The acute shortage of affordable housing**: Tình trạng thiếu hụt trầm trọng nhà ở giá vừa túi tiền.
- **To decentralise commercial hubs**: Phân tán các trung tâm thương mại ra khỏi lõi nội đô.
- **Gentrification**: Hiện tượng tái thiết đô thị khiến tầng lớp thượng lưu chuyển đến và đẩy giá sinh hoạt lên cao.', 2, true),
  ('40000000-0000-4000-c000-000000000036'::uuid, '30000000-0000-4000-c000-000000000012'::uuid, 'tip', 'Áp dụng vào câu luận điểm', '*''Investing in integrated rail systems not only alleviates chronic gridlock but also curbs vehicular emissions in metropolitan centres.''*', 3, true),
  ('40000000-0000-4000-c000-000000000037'::uuid, '30000000-0000-4000-c000-000000000013'::uuid, 'text', 'Các khái niệm công nghệ mới trong đề thi IELTS gần đây', 'Các đề thi IELTS gần đây thường xuyên đề cập tới tác động của Trí tuệ nhân tạo (AI), Tự động hóa (Automation) và Giáo dục từ xa đối với xã hội:
- **Technological disruption**: Sự đột phá công nghệ làm thay đổi toàn bộ thị trường truyền thống.
- **Digital literacy**: Kỹ năng sử dụng công nghệ số và an toàn thông tin.
- **Blended learning**: Mô hình học tập kết hợp giữa trực tiếp trên lớp và trực tuyến.
- **Algorithmic bias**: Định kiến trong thuật toán máy học do dữ liệu huấn luyện thiên vị.', 1, true),
  ('40000000-0000-4000-c000-000000000038'::uuid, '30000000-0000-4000-c000-000000000013'::uuid, 'example', 'Collocations chuyên sâu chủ đề AI & Giáo dục', '- **To cultivate critical thinking skills**: Nuôi dưỡng và rèn luyện kỹ năng tư duy phản biện.
- **To bridge the digital divide**: Thu hẹp khoảng cách tiếp cận công nghệ giữa các tầng lớp xã hội.
- **Personalised learning pathways**: Lộ trình học tập được cá nhân hóa theo năng lực từng học viên.
- **Ethical implications of AI**: Các hệ lụy đạo đức của trí tuệ nhân tạo.', 2, true),
  ('40000000-0000-4000-c000-000000000039'::uuid, '30000000-0000-4000-c000-000000000013'::uuid, 'tip', 'Tư duy phản biện trong đề bài AI thay thế giáo viên', 'Khi bàn về AI trong giáo dục: AI có thể cung cấp phản hồi tức thì và bài tập thích ứng (adaptive exercises), nhưng không thể thay thế giáo viên ở khả năng thấu cảm (empathy), truyền cảm hứng (mentorship) và giáo dục nhân cách đạo đức (moral guidance).', 3, true),
  ('40000000-0000-4000-c000-000000000040'::uuid, '30000000-0000-4000-c000-000000000014'::uuid, 'text', 'Các chuyển dịch lớn trong xã hội và thị trường lao động', 'Các bài đọc và đề viết IELTS thường xuyên khảo sát sự biến đổi của việc làm và văn hóa trong kỷ nguyên toàn cầu hóa:
- **Gig economy**: Nền kinh tế việc làm tự do / thời vụ (freelancer, tài xế công nghệ) không gắn liền với hợp đồng biên chế dài hạn.
- **Socio-economic disparity**: Sự chênh lệch giàu nghèo trong xã hội.
- **Cultural homogenisation**: Hiện tượng đồng nhất hóa văn hóa (văn hóa phương Tây du nhập làm mờ nhạt bản sắc truyền thống).
- **Brain drain**: Hiện tượng chảy máu chất xám (nhân lực tay nghề cao di cư sang các quốc gia phát triển).', 1, true),
  ('40000000-0000-4000-c000-000000000041'::uuid, '30000000-0000-4000-c000-000000000014'::uuid, 'example', 'Collocations nâng cao chủ đề Việc làm & Xã hội', '- **To widen the gap between the affluent and the underprivileged**: Nới rộng khoảng cách giữa người giàu và người yếu thế.
- **Flexible working arrangements**: Chế độ làm việc linh hoạt (làm việc từ xa kết hợp văn phòng).
- **To preserve indigenous traditions**: Gìn giữ các truyền thống bản địa.
- **Job displacement due to automation**: Sự mất việc làm hàng loạt do tự động hóa máy móc.', 2, true),
  ('40000000-0000-4000-c000-000000000042'::uuid, '30000000-0000-4000-c000-000000000014'::uuid, 'tip', 'Từ đồng nghĩa nâng cấp điểm Lexical Resource', '- Thay vì dùng ''Rich and poor'': Dùng **''The affluent and the underprivileged''**.
- Thay vì dùng ''Old people'': Dùng **''The elderly''** hoặc **''Senior citizens''**.
- Thay vì dùng ''Young people'': Dùng **''Adolescents''** hoặc **''The younger demographic''**.', 3, true),
  ('40000000-0000-4000-c000-000000000043'::uuid, '30000000-0000-4000-c000-000000000015'::uuid, 'text', 'Bản chất của kỹ năng Paraphrase trong IELTS', 'Paraphrase không chỉ đơn thuần là dùng từ điển đồng nghĩa (Thesaurus) thay thế từng từ một. Việc thay từ cơ học thường dẫn đến câu văn ngô nghê và sai collocations.

Một bài paraphrase xuất sắc kết hợp đồng thời **4 kỹ thuật**:
1. Sử dụng từ đồng nghĩa phù hợp ngữ cảnh (*Synonyms*).
2. Biến đổi dạng từ (*Word Form Transformation*: Động từ thành Danh từ hóa).
3. Chuyển đổi giữa thể Chủ động và Bị động (*Voice Changing*).
4. Tái cấu trúc hoàn toàn trật tự ý của câu (*Sentence Structure Reorganization*).', 1, true),
  ('40000000-0000-4000-c000-000000000044'::uuid, '30000000-0000-4000-c000-000000000015'::uuid, 'example', 'Phân tích ví dụ Paraphrase 4 cấp độ', '- *Đề bài:* The consumption of fast food has increased dramatically among adolescents.
- *Cấp độ 1 (Thay từ đơn giản):* The intake of junk food has grown significantly among teenagers.
- *Cấp độ 2 (Danh từ hóa + Đổi cấu trúc - Band 7.5+):* There has been **a dramatic surge in fast food consumption** within the younger demographic.
- *Cấp độ 3 (Bị động + Tái cấu trúc):* Fast food is being consumed **at unprecedented rates by teenagers** in recent years.', 2, true),
  ('40000000-0000-4000-c000-000000000045'::uuid, '30000000-0000-4000-c000-000000000015'::uuid, 'tip', 'Nguyên tắc ''Bảo toàn ý nghĩa gốc''', 'Khi paraphrase, hãy luôn kiểm tra xem thông điệp ban đầu có bị thay đổi mức độ hay không. Ví dụ: ''always'' không thể thay bằng ''often''; ''prohibit'' (cấm hoàn toàn) không thể thay bằng ''discourage'' (không khuyến khích).', 3, true),
  ('40000000-0000-4000-c000-000000000046'::uuid, '30000000-0000-4000-c000-000000000016'::uuid, 'text', 'Quy tắc vàng phân biệt True, False và Not Given', 'Dạng bài T/F/NG là nỗi ám ảnh lớn nhất của thí sinh IELTS Reading. Nguyên tắc xác định chân lý khách quan của Cambridge gồm 3 định luật:
- **TRUE (Đúng)**: Ý của nhận định hoàn toàn trùng khớp với thông tin trong bài đọc (dù được diễn đạt bằng ngôn ngữ paraphrase).
- **FALSE (Sai)**: Bài đọc đưa ra thông tin **MÂU THUẪN HOÀN TOÀN** hoặc phủ định trực tiếp nhận định (Nếu nhận định là A, bài đọc nói rõ là Không phải A hoặc Ngược lại).
- **NOT GIVEN (Không có thông tin)**: Bài đọc có thể nhắc tới chủ đề đó, nhưng **KHÔNG CÓ ĐỦ DỮ KIỆN** để khẳng định nhận định là Đúng hay Sai.', 1, true),
  ('40000000-0000-4000-c000-000000000047'::uuid, '30000000-0000-4000-c000-000000000016'::uuid, 'example', 'Bẫy mức độ so sánh (Comparison Trap)', '- *Bài đọc:* The new library opened in 2022 and attracted over 5,000 visitors in its first month.
- *Nhận định 1:* The library welcomed more visitors than the local museum. → **NOT GIVEN** (Bài đọc chỉ nêu số lượng khách của thư viện, hoàn toàn không so sánh với bảo tàng địa phương!).
- *Nhận định 2:* The library remained closed to the public throughout 2022. → **FALSE** (Mâu thuẫn trực tiếp vì bài đọc ghi rõ thư viện đã mở cửa năm 2022).', 2, true),
  ('40000000-0000-4000-c000-000000000048'::uuid, '30000000-0000-4000-c000-000000000016'::uuid, 'warning', 'Cảnh báo bẫy Qualifier (Từ chỉ mức độ tuyệt đối)', 'Hãy đặc biệt chú ý các từ giới hạn phạm vi như *all, only, always, never, completely*. Nếu bài đọc nói *''Many students prefer online lectures''*, nhưng nhận định nói *''ALL students prefer online lectures''* → Đáp án là **FALSE** (vì bài đọc giới hạn là many chứ không phải all)!', 3, true),
  ('40000000-0000-4000-c000-000000000049'::uuid, '30000000-0000-4000-c000-000000000017'::uuid, 'text', 'Bản chất dạng bài Matching Headings', 'Matching Headings (Nối tiêu đề với đoạn văn) là dạng bài kiểm tra khả năng đọc hiểu ý nghĩa tổng thể (Global Comprehension). Một tiêu đề đúng phải bao quát được **toàn bộ nội dung cốt lõi của đoạn**, chứ không phải chỉ nhắc lại một ví dụ hay một con số xuất hiện trong một câu đơn lẻ.', 1, true),
  ('40000000-0000-4000-c000-000000000050'::uuid, '30000000-0000-4000-c000-000000000017'::uuid, 'example', 'Bẫy chi tiết phụ (Detail Trap)', '- *Đoạn văn:* Cả đoạn bàn về sự phát triển của công nghệ in 3D trong xây dựng nhà ở giá rẻ. Trong câu cuối, tác giả lấy ví dụ về một công ty tại Hà Lan đã in thử một cây cầu bê tông.
- *Tiêu đề bẫy:* ''The construction of bridges in the Netherlands'' (Đây là bẫy chi tiết phụ!)
- *Tiêu đề đúng:* ''A revolutionary approach to low-cost housing construction''.', 2, true),
  ('40000000-0000-4000-c000-000000000051'::uuid, '30000000-0000-4000-c000-000000000017'::uuid, 'tip', 'Quy trình 3 bước xử lý Matching Headings chuẩn', '1. Đọc lướt danh sách Headings, gạch chân các từ khóa phân biệt sự khác nhau giữa các tiêu đề.
2. Đọc câu đầu, câu thứ hai và câu cuối của đoạn văn (vị trí thường chứa Topic Sentence hoặc kết luận của đoạn).
3. Tự tóm tắt ý chính của đoạn bằng một câu tiếng Việt trong đầu, sau đó đối chiếu tìm tiêu đề tương ứng nhất.', 3, true),
  ('40000000-0000-4000-c000-000000000052'::uuid, '30000000-0000-4000-c000-000000000018'::uuid, 'text', 'Bẫy tự đính chính (Self-correction Trap) trong Listening', 'Trong bài thi IELTS Listening, người nói rất hiếm khi đọc thẳng đáp án mà không có yếu tố gây nhiễu (Distractor). Một kịch bản phổ biến là **người nói đưa ra một thông tin ban đầu, sau đó lập tức sửa lại** bằng các từ nối chuyển hướng như *''Oh, sorry, I gave you the wrong date''*, *''Actually, it has changed to...''*, hoặc *''I used to live there, but I moved last year.''*.', 1, true),
  ('40000000-0000-4000-c000-000000000053'::uuid, '30000000-0000-4000-c000-000000000018'::uuid, 'example', 'Ví dụ kịch bản thoại có Distractor', '- *Đề bài:* Meeting time: [___]
- *Audio:* Clerk: ''We normally hold the workshop at 10 a.m.'' (Thí sinh vội ghi 10:00). ''However, because the room is being renovated, we have pushed it back to **11:30**.''
- *Phân tích:* 10:00 a.m là bẫy nhiễu. Đáp án đúng là **11:30**.', 2, true),
  ('40000000-0000-4000-c000-000000000054'::uuid, '30000000-0000-4000-c000-000000000018'::uuid, 'tip', 'Thời gian đọc trước câu hỏi (Pre-reading)', 'Tận dụng tối đa khoảng thời gian 30-45 giây trước mỗi section để gạch chân từ khóa và **dự đoán loại từ** cần điền: Danh từ số ít hay số nhiều? Tên riêng? Con số hay ngày tháng? Sự chuẩn bị này giúp não bộ tự động kích hoạt bộ lọc âm thanh khi audio phát.', 3, true),
  ('40000000-0000-4000-c000-000000000055'::uuid, '30000000-0000-4000-c000-000000000019'::uuid, 'text', 'Cấu trúc đoạn thân bài chuẩn PEEL', 'Lỗi phổ biến nhất khiến bài luận Task 2 bị kẹt ở Band 5.5-6.0 là **''liệt kê ý tưởng''** (đưa ra quá nhiều ý tưởng nhưng không đào sâu giải thích nguyên nhân và hệ quả).

Cấu trúc **PEEL** giúp bạn phát triển một luận điểm sâu sắc và thuyết phục:
- **P - Point (Luận điểm)**: Câu mở đoạn nêu rõ ý kiến chính.
- **E - Explanation (Giải thích)**: Tại sao điều đó xảy ra? Cơ chế vận hành như thế nào? (Trả lời câu hỏi Why? How?).
- **E - Example (Ví dụ minh họa)**: Dẫn chứng thực tế, số liệu hoặc nghiên cứu cụ thể để chứng minh.
- **L - Link (Câu kết nối)**: Tóm tắt ý nghĩa và kết nối ngược trở lại câu hỏi của đề bài.', 1, true),
  ('40000000-0000-4000-c000-000000000056'::uuid, '30000000-0000-4000-c000-000000000019'::uuid, 'example', 'Ví dụ triển khai một đoạn thân bài PEEL hoàn chỉnh', '- **[Point]:** The primary benefit of subsidising public transport is the marked reduction in traffic congestion.
- **[Explanation]:** When fares are lowered and service frequency is upgraded, commuters are economically incentivised to abandon private motor vehicles in favour of buses and trains. This significantly diminishes the volume of automobiles circulating on urban roadways during rush hours.
- **[Example]:** A pertinent example is Luxembourg, which became the first nation to offer entirely free public transit, resulting in a noticeable decline in downtown gridlock.
- **[Link]:** Consequently, targeted state subsidies can function as a potent mechanism for enhancing urban mobility.', 2, true),
  ('40000000-0000-4000-c000-000000000057'::uuid, '30000000-0000-4000-c000-000000000019'::uuid, 'tip', 'Quy tắc 5 phút lập dàn ý trước khi viết', 'Dành 5 phút đầu tiên để phân tích đề bài, xác định dạng câu hỏi (Opinion, Discussion, Problem-Solution, Two-part) và gạch đầu dòng 2 luận điểm chính cho 2 đoạn thân bài. Đừng bao giờ bắt tay vào viết ngay khi chưa có dàn ý!', 3, true),
  ('40000000-0000-4000-c000-000000000058'::uuid, '30000000-0000-4000-c000-000000000020'::uuid, 'text', 'Bản chất tiêu chí Fluency & Coherence trong Speaking', 'Nhiều thí sinh hiểu nhầm rằng Fluency là phải bắn tiếng Anh thật nhanh như gió. Thực chất, **Fluency (Độ trôi chảy)** là khả năng duy trì dòng nói liên tục, tốc độ ổn định, không ngập ngừng quá lâu để tìm từ vựng và câu trả lời có độ dài tương xứng.

Trong Part 1, câu trả lời lý tưởng kéo dài từ **2 đến 4 câu**. Đừng chỉ trả lời cộc lốc *''Yes, I do''* hoặc *''No, I don''t''*.', 1, true),
  ('40000000-0000-4000-c000-000000000059'::uuid, '30000000-0000-4000-c000-000000000020'::uuid, 'example', 'Công thức AREA mở rộng câu trả lời tự nhiên', '- **A - Answer (Trả lời trực tiếp)**: *''Yes, I absolutely enjoy cooking at home.''*
- **R - Reason (Nêu nguyên nhân)**: *''Mainly because it gives me full control over nutritional ingredients and helps me unwind after a demanding workday.''*
- **E - Example (Ví dụ cụ thể)**: *''For instance, on weekends, I often experiment with authentic pasta dishes for my family.''*
- **A - Alternative (Ý kiến mở rộng/ngược lại)**: *''That being said, on hectic weekdays, I sometimes order food delivery to save time.''*', 2, true),
  ('40000000-0000-4000-c000-000000000060'::uuid, '30000000-0000-4000-c000-000000000020'::uuid, 'tip', 'Kỹ thuật câu giờ tự nhiên (Fillers & Discourse Markers)', 'Khi cần thêm 2-3 giây suy nghĩ, hãy dùng các cụm tự nhiên thay vì phát ra âm thanh ngập ngừng ''uhm, ahh'':
- *''Well, to be perfectly honest, that''s not something I''ve thought about before, but...''* 
- *''That''s an intriguing question. I would say that...''*', 3, true)
on conflict (id) do nothing;

