  ('71000000-0000-4000-c000-000000000008'::uuid, '70000000-0000-4000-c000-000000000008'::uuid, 1, 'Luyện tập: Passive Voice và Cautious Language', 'Biến đổi các câu nói tuyệt đối hóa thành văn phong học thuật khách quan và trang trọng.', 'Hoàn thành tất cả 6 câu hỏi. Bài làm tự động lưu sau mỗi câu và giải thích mở sau khi nộp.', 'intermediate', 'draft', true, null),
  ('71000000-0000-4000-c000-000000000009'::uuid, '70000000-0000-4000-c000-000000000009'::uuid, 1, 'Luyện tập: Inversion và Cleft Sentences nâng cao', 'Chuyển đổi câu xuôi sang cấu trúc đảo ngữ và câu chẻ ăn điểm ngữ pháp cao.', 'Hoàn thành tất cả 6 câu hỏi. Bài làm tự động lưu sau mỗi câu và giải thích mở sau khi nộp.', 'advanced', 'draft', true, null),
