  ('71000000-0000-4000-c000-000000000014'::uuid, '70000000-0000-4000-c000-000000000014'::uuid, 1, 'Luyện tập: Xã hội, Việc làm & Toàn cầu hóa', 'Kiểm tra từ vựng về thị trường việc làm, chênh lệch xã hội và bảo tồn văn hóa.', 'Hoàn thành tất cả 6 câu hỏi. Bài làm tự động lưu sau mỗi câu và giải thích mở sau khi nộp.', 'intermediate', 'draft', true, null),
  ('71000000-0000-4000-c000-000000000015'::uuid, '70000000-0000-4000-c000-000000000015'::uuid, 1, 'Luyện tập: Academic Collocations và Paraphrasing', 'Thực hành nhận diện và viết lại câu sử dụng collocations tự nhiên và biến đổi cấu trúc linh hoạt.', 'Hoàn thành tất cả 6 câu hỏi. Bài làm tự động lưu sau mỗi câu và giải thích mở sau khi nộp.', 'intermediate', 'draft', true, null),
