  ('72000000-0000-4000-c000-000000000001'::uuid, '71000000-0000-4000-c000-000000000001'::uuid, 1, 'single_choice', 'Tổng thời gian làm bài chính thức của kỹ năng Reading trong kỳ thi IELTS là bao nhiêu phút?', 1),
  ('72000000-0000-4000-c000-000000000002'::uuid, '71000000-0000-4000-c000-000000000001'::uuid, 2, 'single_choice', 'Nếu thí sinh có điểm các kỹ năng: L: 6.5, R: 7.0, W: 6.0, S: 6.5, điểm Overall sẽ là bao nhiêu?', 1),
