-- 13. Ingest Grammar Topic Versions (as draft then publish)
  id, grammar_topic_id, version, title, explanation_markdown, examples, common_mistakes, difficulty, status, related_exercise_set_id, published_at
) values
  ('51000000-0000-4000-c000-000000000001'::uuid, '50000000-0000-4000-c000-000000000001'::uuid, 1, 'Subject-Verb Agreement nâng cao', 'Quy tắc xác định danh từ trung tâm (Head Noun) khi có cụm giới từ chen ngang, đại từ bất định và cấu trúc ''The number of'' vs ''A number of''.', '[{"correct":"The quality of these experimental programs has improved.","note":"Quality là danh từ trung tâm số ít."},{"correct":"A number of applicants have submitted their dossiers.","note":"A number of đi với động từ số nhiều."}]'::jsonb, '[{"wrong":"The number of students are increasing.","correction":"Dùng ''is increasing'' vì ''The number'' là số ít."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000001'::uuid, null),
  ('51000000-0000-4000-c000-000000000002'::uuid, '50000000-0000-4000-c000-000000000002'::uuid, 1, 'Câu phức và Mệnh đề phụ thuộc', 'Xây dựng các câu phức học thuật chuẩn mực sử dụng liên từ phụ thuộc nhượng bộ (Although, Whereas) và quan hệ nguyên nhân - hệ quả (Since, Given that).', '[{"correct":"Although capital costs are substantial, long-term savings are guaranteed.","note":"Dùng Although ở mệnh đề phụ thì không dùng But ở mệnh đề chính."}]'::jsonb, '[{"wrong":"Although it was raining, but we still went out.","correction":"Bỏ ''but'' khi đã có ''Although''."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000002'::uuid, null),
  ('51000000-0000-4000-c000-000000000003'::uuid, '50000000-0000-4000-c000-000000000003'::uuid, 1, 'Thể bị động khách quan và Impersonal Style', 'Ứng dụng cấu trúc ''It is widely believed that...'' và ''X is deemed to be...'' để tạo giọng văn học thuật khách quan, không thiên vị cá nhân.', '[{"correct":"It is widely acknowledged that early childhood education is vital.","note":"Cấu trúc bị động khách quan trang trọng."}]'::jsonb, '[{"wrong":"People believes that technology is bad.","correction":"Dùng ''It is argued that excessive technology usage has negative impacts.''"}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000003'::uuid, null),
  ('51000000-0000-4000-c000-000000000004'::uuid, '50000000-0000-4000-c000-000000000004'::uuid, 1, 'Đảo ngữ với trạng từ phủ định (Inversion)', 'Cấu trúc đảo trợ động từ lên trước chủ ngữ khi đứng đầu câu bằng ''Not only'', ''Rarely'', ''Seldom'', ''Under no circumstances''.', '[{"correct":"Not only does automation increase productivity, but it also reduces errors.","note":"Đảo trợ động từ does lên trước automation."}]'::jsonb, '[{"wrong":"Not only automation increases productivity, but...","correction":"Phải đảo ngữ: ''Not only does automation increase...''"}]'::jsonb, 'advanced', 'draft', '70000000-0000-4000-c000-000000000004'::uuid, null),
  ('51000000-0000-4000-c000-000000000005'::uuid, '50000000-0000-4000-c000-000000000005'::uuid, 1, 'Phương tiện liên kết đoạn Cohesive Devices', 'Sử dụng linh hoạt các trạng từ liên kết (Consequently, Thus, Nevertheless) và đặt liên từ vào giữa câu để tránh bẫy máy móc.', '[{"correct":"Public transport is subsidised; many residents, however, still drive.","note":"Đặt however vào giữa câu tự nhiên."}]'::jsonb, '[{"wrong":"Firstly, X. Secondly, Y. Thirdly, Z.","correction":"Hạn chế liệt kê cơ học; hãy dùng các liên từ chỉ nhân quả và tương phản."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000005'::uuid, null),
  ('51000000-0000-4000-c000-000000000006'::uuid, '50000000-0000-4000-c000-000000000006'::uuid, 1, 'Mệnh đề quan hệ và Mệnh đề phân từ rút gọn', 'Rút gọn mệnh đề quan hệ chủ động sang V-ing và bị động sang V3/ed để câu văn cô đọng, súc tích chuẩn học thuật.', '[{"correct":"The proposal submitted by the municipal committee was approved.","note":"Rút gọn của ''which was submitted''."}]'::jsonb, '[{"wrong":"The proposal which submitted yesterday was approved.","correction":"Thiếu ''was'' trong câu bị động chưa rút gọn."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000006'::uuid, null),
  ('51000000-0000-4000-c000-000000000007'::uuid, '50000000-0000-4000-c000-000000000007'::uuid, 1, 'Câu điều kiện nâng cao & Mixed Conditionals', 'Sử dụng câu điều kiện loại 2, 3 và câu điều kiện hỗn hợp để lập luận các kịch bản giả định trong Writing Task 2.', '[{"correct":"Had governments acted earlier, coastal communities would not face relocation today.","note":"Đảo ngữ câu điều kiện loại 3 kết hợp hiện tại."}]'::jsonb, '[{"wrong":"If governments acted earlier, they will save money.","correction":"Lệch thì: ''If governments acted earlier, they would save money.''"}]'::jsonb, 'advanced', 'draft', '70000000-0000-4000-c000-000000000007'::uuid, null),
  ('51000000-0000-4000-c000-000000000008'::uuid, '50000000-0000-4000-c000-000000000008'::uuid, 1, 'Mạo từ A, An, The trong văn cảnh học thuật', 'Sử dụng mạo từ xác định ''The'' cho các đối tượng duy nhất hoặc đã xác định, và không dùng mạo từ trước danh từ số nhiều/không đếm được mang nghĩa tổng quát.', '[{"correct":"Education is a fundamental human right.","note":"Education mang nghĩa chung không dùng ''The''."}]'::jsonb, '[{"wrong":"The education is vital for all people.","correction":"Bỏ ''The'' khi nói về giáo dục nói chung."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000008'::uuid, null),
  ('51000000-0000-4000-c000-000000000009'::uuid, '50000000-0000-4000-c000-000000000009'::uuid, 1, 'Kỹ thuật Danh từ hóa (Nominalization)', 'Biến đổi động từ hoặc tính từ thành danh từ tương ứng để tăng mật độ thông tin học thuật (Lexical Density).', '[{"correct":"The rapid expansion of metropolitan areas has strained local utilities.","note":"Thay vì ''Because cities expand rapidly, they strain...''"}]'::jsonb, '[{"wrong":"We need to make our transport better.","correction":"Dùng: ''The enhancement of public transport infrastructure is imperative.''"}]'::jsonb, 'advanced', 'draft', '70000000-0000-4000-c000-000000000009'::uuid, null),
  ('51000000-0000-4000-c000-000000000010'::uuid, '50000000-0000-4000-c000-00000000000a'::uuid, 1, 'Kỹ thuật Ngôn ngữ cẩn trọng (Hedging)', 'Sử dụng modal verbs (may, could), trạng từ (presumably, potentially) và động từ chỉ xu hướng (tend to) để tránh tuyệt đối hóa phiến diện.', '[{"correct":"Excessive smartphone usage may potentially impair cognitive attention spans.","note":"Ngôn ngữ cẩn trọng khoa học."}]'::jsonb, '[{"wrong":"Smartphones definitely ruin human intellect.","correction":"Nói quá tuyệt đối, thiếu tính học thuật khách quan."}]'::jsonb, 'intermediate', 'draft', '70000000-0000-4000-c000-000000000010'::uuid, null)
on conflict (id) do nothing;

